        { title: "Fix Fix Import Statement 5", level: "expert", desc: "Importing module with wrong name.", bug: "import math\nprint(math.sqr(16))", solution: "import math\nprint(math.sqrt(16))", test: "// Python import" },
        { title: "Fix Fix List Comprehension 5", level: "expert", desc: "List comprehension syntax error.", bug: "squares = [x**2 for x in range(5)]\nprint(squares)", solution: "squares = [x**2 for x in range(5)]\nprint(squares)", test: "// Python comprehension" },
        { title: "Fix Fix String Upper 5", level: "expert", desc: "Calling method that doesn't exist on string.", bug: "s = 'hello'\nprint(s.uppercase())", solution: "s = 'hello'\nprint(s.upper())", test: "// Python string method" }
